        verified.comparison.baseline_suite,
        verified.comparison.candidate_suite,
        verified.baseline,
        verified.candidate,
        verified.cases,
    ))
}

fn from_parts(
    comparison_cid: String,
    baseline_suite: String,
    candidate_suite: String,
    baseline: super::benchmark_suite::ComparableSuite,
    candidate: super::benchmark_suite::ComparableSuite,
