fn forge_relation(
    cwd: &Path,
    cid: &str,
    relation: &str,
    equal: bool,
    candidate_output: Option<&str>,
) -> String {
    let store = ObjectStore::open(cwd);
    let Node::Value(Value::Map(mut entries)) =
        decode_node(&store.get_canonical(cid).unwrap()).unwrap()
    else {
        panic!("comparison must be a value map")
    };
    set_field(
        &mut entries,
        "behavior_relation",
