pub(super) fn exact(
    prepared: &PreparedResolution,
    registry: &HotpathRegistry,
) -> Result<Option<ResolutionDecision>, ResolverError> {
    let mut matches = Vec::new();
    for (index, binding) in prepared.candidates.iter().enumerate() {
        let hotpath = registry
            .get(&binding.id)
            .ok_or(ResolverError::StaleCatalog)?;
        for alias in hotpath.labels.values().flat_map(|labels| &labels.aliases) {
            if let Some(args) = match_alias(&prepared.input, alias) {
                if let Ok(selection) = prepared.bind(registry, index, args) {
                    if !matches.iter().any(|prior: &super::ResolvedSelection| {
                        prior.id == selection.id && prior.arguments == selection.arguments
                    }) {
                        matches.push(selection);
                    }
                }
            }
        }
    }
    if matches.len() > 1 {
        return Ok(Some(ResolutionDecision::Abstained(
            super::Abstention::Clarify,
        )));
    }
    Ok(matches.pop().map(ResolutionDecision::Selected))
}

fn match_alias(input: &str, alias: &str) -> Option<BTreeMap<String, Value>> {
    let input = input.trim();
    let Some((prefix, rest)) = alias.split_once('{') else {
        return input.eq_ignore_ascii_case(alias).then(BTreeMap::new);
    };
    let (slot, suffix) = rest.split_once('}')?;
    if slot.is_empty() || suffix.contains(['{', '}']) || prefix.contains('}') {
        return None;
    }
    if !input.starts_with(prefix)
        || !input.ends_with(suffix)
        || input.len() < prefix.len() + suffix.len()
    {
        return None;
    }
    let value = &input[prefix.len()..input.len() - suffix.len()];
    if value.is_empty() {
        return None;
    }
    Some(
        [(slot.to_string(), Value::String(value.to_string()))]
            .into_iter()
            .collect(),
    )
}

